-- Private, draft-scoped voice intake. Browser clients receive only a short-lived
-- upload capability generated by the application; this bucket is never public.

insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values (
  'voice-memos',
  'voice-memos',
  false,
  15728640,
  array['audio/webm', 'audio/mp4', 'audio/mpeg', 'audio/ogg', 'audio/wav']
)
on conflict (id) do update
set public = false,
    file_size_limit = excluded.file_size_limit,
    allowed_mime_types = excluded.allowed_mime_types;

alter table public.voice_memos
  alter column build_request_id drop not null,
  add column request_draft_id uuid references public.request_drafts(id) on delete cascade,
  add column original_filename text,
  add column mime_type text,
  add column byte_length integer check (byte_length is null or byte_length >= 0);

alter table public.voice_memos
  add constraint voice_memos_exactly_one_owner check (
    (build_request_id is not null and request_draft_id is null)
    or (build_request_id is null and request_draft_id is not null)
  );

create unique index voice_memos_request_draft_id_key
  on public.voice_memos (request_draft_id);

create table public.voice_memo_transcription_jobs (
  id uuid primary key default gen_random_uuid(),
  voice_memo_id uuid not null unique references public.voice_memos(id) on delete cascade,
  provider text not null default 'deepgram',
  model text not null default 'nova-3',
  status text not null default 'queued' check (status in ('queued', 'running', 'succeeded', 'retryable_failed', 'terminal_failed')),
  attempt_count smallint not null default 0 check (attempt_count between 0 and 3),
  max_attempts smallint not null default 3 check (max_attempts between 1 and 3),
  provider_request_id text,
  language text,
  confidence numeric check (confidence is null or (confidence >= 0 and confidence <= 1)),
  error_code text,
  next_attempt_at timestamptz,
  started_at timestamptz,
  completed_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index voice_memo_transcription_jobs_ready_idx
  on public.voice_memo_transcription_jobs (status, next_attempt_at, created_at)
  where status in ('queued', 'retryable_failed');

create trigger voice_memo_transcription_jobs_set_updated_at
  before update on public.voice_memo_transcription_jobs
  for each row execute function public.set_updated_at();

alter table public.voice_memo_transcription_jobs enable row level security;

-- There are intentionally no client Storage or job policies. The application
-- service role issues narrowly scoped signed upload URLs and the worker is
-- server-only; customer reads use the existing build-request policy after the
-- memo is attached to a submitted request.
